// Modified 2026-10-22: MP3-only build; no AAC, examples or npm encoder package.
// Encoder preparation and esbuild options are unchanged.
import { build } from 'esbuild';
import { mkdir, writeFile } from 'node:fs/promises';
import { prepareLamejs } from './scripts/prepare-lamejs.mjs';
const encoderEntry = await prepareLamejs();
const worker = await build({
  entryPoints: ['src/mp3/worker.ts'], bundle: true, write: false, format: 'iife',
  platform: 'browser', target: 'es2022', minify: true, legalComments: 'inline',
  plugins: [{ name: 'local-mp3-encoder', setup(builder) {
    builder.onResolve({ filter: /^\.\/encoder\.js$/ }, () => ({ path: encoderEntry }));
  } }],
});
await mkdir('dist', { recursive: true });
await writeFile('dist/mp3-worker-source.js', `// Generated by scripts/build-mp3.mjs.\nexport const mp3WorkerSource = ${JSON.stringify(worker.outputFiles[0].text)};\n`);
await build({
  entryPoints: ['dist/mp3.js'], bundle: true, outfile: 'dist/browser-mp3.js',
  format: 'iife', globalName: 'BrowserMp3', platform: 'browser', target: 'es2022', minify: true,
  banner: { js: '/*! Browser MP3: MIT wrapper; includes modified lamejs 1.2.7 (LGPL-3.0), with JavaScript VBR/ABR extensions. See THIRD_PARTY_NOTICES.md. */' },
});
